python3 -c "
from collections import deque
from itertools import islice

def consume(iterator, n=None):
    if n is None:
        list(iterator)
    else:
        next(islice(iterator, n, n), None)

class seekable_v4:
    def __init__(self, iterable, maxlen=None):
        self._source = iter(iterable)
        if maxlen is None:
            self._cache = []
        else:
            self._cache = deque([], maxlen)
        self._index = None
        self._current_pos = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self._index is not None:
            try:
                item = self._cache[self._index]
            except IndexError:
                self._index = None
            else:
                self._index += 1
                self._current_pos = self._index
                return item

        item = next(self._source)
        self._cache.append(item)
        self._current_pos = len(self._cache)
        return item

    def seek(self, index):
        self._index = index
        remainder = index - len(self._cache)
        if remainder > 0:
            consume(self, remainder)

    def relative_seek(self, offset):
        new_pos = self._current_pos + offset
        if new_pos < 0:
            raise IndexError('Cannot seek before start')
        self._current_pos = new_pos
        # Now need to actually seek to _current_pos
        # But we also need to update _index appropriately
        if new_pos >= len(self._cache):
            self._index = new_pos
            remainder = new_pos - len(self._cache)
            if remainder > 0:
                consume(self, remainder)
        else:
            self._index = new_pos

it = seekable_v4((str(n) for n in range(20)))
print(f'next: {next(it)}, {next(it)}, {next(it)}')
print(f'_current_pos={it._current_pos}, _index={it._index}')
it.relative_seek(1)
print(f'After relative_seek(1): _current_pos={it._current_pos}, _index={it._index}')
print(f'next: {next(it)}')
print(f'_current_pos={it._current_pos}, _index={it._index}')
it.relative_seek(-2)
print(f'After relative_seek(-2): _current_pos={it._current_pos}, _index={it._index}')
print(f'next: {next(it)}')
